fn a_string_enum_prop_is_the_union_of_its_values() {
    let (props, diagnostics) = props_of(&[(
        "case.tsx",
        r#"
        enum Tone { Primary = "primary", Secondary = "secondary" }
        export function C(props: { tone: Tone; literal: "primary" | "secondary" }) { return <b />; }
    }
}

